@Service
public class ProviderService {

    private static final int TIMEOUT_MILLIS = 10000;

    private final ModelProviderMapper providerMapper;
    private final UserMapper userMapper;
    private final ObjectMapper objectMapper = new ObjectMapper();

    public ProviderService(ModelProviderMapper providerMapper, UserMapper userMapper) {
        this.providerMapper = providerMapper;
        this.userMapper = userMapper;
    }

    public Map<String, Object> register(String username, ProviderRegisterRequest request) {
        User user = userMapper.findByUsername(username);
        if (user == null) {
            return null;
        }
        ModelProvider provider = new ModelProvider();
        provider.setUserId(user.getId());
        provider.setName(request.getName());
        provider.setBaseUrl(request.getBaseUrl());
        provider.setApiKey(request.getApiKey());
        provider.setModelId(request.getModelId());
        provider.setStatus("PENDING");
        provider.setErrorMessage(null);
        provider.setLastValidatedAt(null);
        provider.setCreatedAt(LocalDateTime.now());
        providerMapper.insert(provider);

        Map<String, Object> data = new LinkedHashMap<>();
        data.put("id", provider.getId());
        data.put("name", provider.getName());
        data.put("baseUrl", provider.getBaseUrl());
        data.put("modelId", provider.getModelId());
        data.put("status", provider.getStatus());
        data.put("createdAt", toDateString(provider.getCreatedAt()));
        return data;
    }

    public Map<String, Object> validateProvider(String username, Long providerId) {
        User user = userMapper.findByUsername(username);
        ModelProvider provider = providerMapper.findById(providerId);
        if (user == null || provider == null || !provider.getUserId().equals(user.getId())) {
            return null;
        }

        String status;
        String errorMessage;
        try {
            if (isBlank(provider.getBaseUrl()) || isBlank(provider.getApiKey()) || isBlank(provider.getModelId())) {
                status = "ERROR";
                errorMessage = "Provider is missing baseUrl, apiKey or modelId, validation was not performed";
            } else {
                Integer phase1Status = callProvider("GET",
                        provider.getBaseUrl() + "/models/" + provider.getModelId(),
                        provider.getApiKey(), null, null);
                if (phase1Status != null && (phase1Status == 401 || phase1Status == 403)) {
                    status = "INVALID";
                    errorMessage = "API key is invalid (HTTP " + phase1Status + ")";
                } else if (phase1Status == null || phase1Status == 404) {
                    Integer phase2Status = callProvider("POST",
                            provider.getBaseUrl() + "/v1/chat/completions",
                            provider.getApiKey(), "application/json", buildProbeBody(provider.getModelId()));
                    if (phase2Status != null && (phase2Status == 401 || phase2Status == 403)) {
                        status = "INVALID";
                        errorMessage = "API key is invalid (HTTP " + phase2Status + ")";
                    } else if (phase2Status == null) {
                        status = "ERROR";
                        errorMessage = "Connection failed";
                    } else {
                        status = "VALID";
                        errorMessage = null;
                    }
                } else {
                    status = "VALID";
                    errorMessage = null;
                }
            }
        } catch (Exception e) {
            status = "ERROR";
            errorMessage = e.getMessage();
        }

        provider.setStatus(status);
        provider.setErrorMessage(errorMessage);
