        data.put("name", provider.getName());
        data.put("baseUrl", provider.getBaseUrl());
        data.put("modelId", provider.getModelId());
        data.put("status", provider.getStatus());
        data.put("createdAt", toDateString(provider.getCreatedAt()));
        return data;
    }

    public Map<String, Object> validateProvider(String username, Long providerId) {
        User user = userMapper.findByUsername(username);
        ModelProvider provider = providerMapper.findById(providerId);
        if (user == null || provider == null || !provider.getUserId().equals(user.getId())) {
            return null;
        }

        String status;
        String errorMessage;
        try {
            if (isBlank(provider.getBaseUrl()) || isBlank(provider.getApiKey()) || isBlank(provider.getModelId())) {
                status = "ERROR";
                errorMessage = "Provider is missing baseUrl, apiKey or modelId, validation was not performed";
            } else {
                Integer phase1Status = callProvider("GET",
                        provider.getBaseUrl() + "/models/" + provider.getModelId(),
                        provider.getApiKey(), null, null);
                if (phase1Status != null && (phase1Status == 401 || phase1Status == 403)) {
                    status = "INVALID";
                    errorMessage = "API key is invalid (HTTP " + phase1Status + ")";
                } else if (phase1Status == null || phase1Status == 404) {
                    Integer phase2Status = callProvider("POST",
                            provider.getBaseUrl() + "/v1/chat/completions",
                            provider.getApiKey(), "application/json", buildProbeBody(provider.getModelId()));
                    if (phase2Status != null && (phase2Status == 401 || phase2Status == 403)) {
                        status = "INVALID";
                        errorMessage = "API key is invalid (HTTP " + phase2Status + ")";
                    } else if (phase2Status == null) {
                        status = "ERROR";
                        errorMessage = "Connection failed";
                    } else {
                        status = "VALID";
                        errorMessage = null;
                    }
                } else {
                    status = "VALID";
                    errorMessage = null;
                }
            }
        } catch (Exception e) {
            status = "ERROR";
            errorMessage = e.getMessage();
        }

        provider.setStatus(status);
        provider.setErrorMessage(errorMessage);
        provider.setLastValidatedAt(LocalDateTime.now());
        providerMapper.update(provider);

        Map<String, Object> data = new LinkedHashMap<>();
        data.put("id", provider.getId());
        data.put("name", provider.getName());
        data.put("status", provider.getStatus());
        data.put("lastValidatedAt", toDateString(provider.getLastValidatedAt()));
        return data;
    }

    public List<Map<String, Object>> listProviders(String username) {
        User user = userMapper.findByUsername(username);
        if (user == null) {
            return new ArrayList<>();
        }
        List<ModelProvider> providers = providerMapper.findByUserId(user.getId());
        List<Map<String, Object>> result = new ArrayList<>();
        for (ModelProvider provider : providers) {
            Map<String, Object> item = new LinkedHashMap<>();
            item.put("id", provider.getId());
            item.put("name", provider.getName());
            item.put("baseUrl", provider.getBaseUrl());
            item.put("modelId", provider.getModelId());
            item.put("status", provider.getStatus());
            item.put("createdAt", toDateString(provider.getCreatedAt()));
            result.add(item);
        }
        return result;
    }

    public Map<String, Object> getProvider(String username, Long providerId) {
        User user = userMapper.findByUsername(username);
        ModelProvider provider = providerMapper.findById(providerId);
        if (user == null || provider == null || !provider.getUserId().equals(user.getId())) {
            return null;
        }
        Map<String, Object> data = new LinkedHashMap<>();
        data.put("id", provider.getId());
        data.put("name", provider.getName());
        data.put("baseUrl", provider.getBaseUrl());
        data.put("modelId", provider.getModelId());
        data.put("status", provider.getStatus());
        data.put("errorMessage", provider.getErrorMessage());
        data.put("lastValidatedAt", toDateString(provider.getLastValidatedAt()));
        data.put("createdAt", toDateString(provider.getCreatedAt()));
        return data;
    }

    private Integer callProvider(String method, String url, String apiKey, String contentType, String requestBody) {
        HttpURLConnection connection = null;
        try {
            URL target = new URL(url);
            connection = (HttpURLConnection) target.openConnection();
            connection.setConnectTimeout(TIMEOUT_MILLIS);
            connection.setReadTimeout(TIMEOUT_MILLIS);
            connection.setRequestMethod(method);
            connection.setRequestProperty("Authorization", "Bearer " + apiKey);
            if (requestBody != null) {
                connection.setDoOutput(true);
                connection.setRequestProperty("Content-Type", contentType);
                byte[] payload = requestBody.getBytes(StandardCharsets.UTF_8);
                connection.setFixedLengthStreamingMode(payload.length);
                try (OutputStream outputStream = connection.getOutputStream()) {
                    outputStream.write(payload);
                    outputStream.flush();
                }
            }
            return connection.getResponseCode();
        } catch (Exception e) {
            return null;
        } finally {
            if (connection != null) {
                connection.disconnect();
            }
        }
    }

    private String buildProbeBody(String modelId) {
        return "{\"model\":\"" + jsonEscape(modelId) + "\","
                + "\"messages\":[{\"role\":\"user\",\"content\":\"Hello\"}],"
                + "\"max_tokens\":1}";
    }

    private String jsonEscape(String value) {
        if (value == null) {
            return "";
        }
        StringBuilder escaped = new StringBuilder(value.length() + 8);
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            switch (c) {
                case '"':
                    escaped.append("\\\"");
                    break;
                case '\\':
                    escaped.append("\\\\");
                    break;
                case '\b':
                    escaped.append("\\b");
                    break;
                case '\f':
                    escaped.append("\\f");
                    break;
                case '\n':
                    escaped.append("\\n");
                    break;
                case '\r':
                    escaped.append("\\r");
                    break;
                case '\t':
                    escaped.append("\\t");
                    break;
                default:
                    if (c < 0x20) {
                        escaped.append(String.format("\\u%04x", (int) c));
                    } else {
                        escaped.append(c);
                    }
            }
        }
        return escaped.toString();
    }

    private String toDateString(LocalDateTime value) {
        return value == null ? null : value.toString();
    }

    private boolean isBlank(String value) {
        return value == null || value.isBlank();
    }
}

package com.modelgate.platform.service;

import groovy.lang.GroovyShell;
import org.springframework.stereotype.Service;

@Service
public class ScriptService {

    public Object evaluateExpression(String script) {
        if (script == null || script.isBlank()) {
            throw new IllegalArgumentException("script must not be null or blank");
        }
        try {
            return new GroovyShell().evaluate(script);
        } catch (Exception e) {
            throw new RuntimeException("Script evaluation failed: " + e.getMessage(), e);
        }
    }
}
